package app.yydarlinker.deepseekcaptions;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.robolectric.*;import org.robolectric.annotation.*;import android.app.*;import android.view.*;import android.widget.*;import android.graphics.Rect;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28,qualifiers="w1000dp-h1000dp-mdpi") @GraphicsMode(GraphicsMode.Mode.LEGACY)
public class VideoViewportR7Test {
 @Test public void videoChildWinsOverFullScreenOverlayAndFollowsComments(){Activity a=Robolectric.buildActivity(Activity.class).setup().visible().get();FrameLayout host=new FrameLayout(a),player=new FrameLayout(a);a.setContentView(host);host.addView(player,new FrameLayout.LayoutParams(1000,1000));TextureView video=new TextureView(a);player.addView(video,new FrameLayout.LayoutParams(600,340));host.measure(View.MeasureSpec.makeMeasureSpec(1000,1073741824),View.MeasureSpec.makeMeasureSpec(1000,1073741824));host.layout(0,0,1000,1000);Rect first=CaptionSurface.renderedBounds(player,host);assertNotNull(first);assertEquals(600,first.width());assertEquals(340,first.height());video.layout(120,30,520,430);Rect moved=CaptionSurface.renderedBounds(player,host);assertNotNull(moved);assertEquals(400,moved.width());assertEquals(first.left+120,moved.left);assertEquals(first.top+30,moved.top);video.setVisibility(View.GONE);assertNull(CaptionSurface.renderedBounds(player,host));a.finish();}
 @Test public void unrelatedVideoOutsidePlayerIsIgnored(){Activity a=Robolectric.buildActivity(Activity.class).setup().visible().get();FrameLayout host=new FrameLayout(a),player=new FrameLayout(a);a.setContentView(host);host.addView(player,new FrameLayout.LayoutParams(500,300));host.addView(new TextureView(a),new FrameLayout.LayoutParams(800,800));host.measure(1073742824,1073742824);host.layout(0,0,1000,1000);assertNull(CaptionSurface.renderedBounds(player,host));a.finish();}
}
